import { STORAGE_KEYS } from './constants'

// Clears what the user generated by taking tests. Bookmarks and the sample-data toggle are kept.
export function resetLearningData() {
  const keys = [STORAGE_KEYS.attempts, STORAGE_KEYS.mistakes, STORAGE_KEYS.mistakeEdits, STORAGE_KEYS.planProgress]
  try {
    keys.forEach((key) => window.localStorage.removeItem(key))
  } catch {
    /* storage unavailable: nothing to clear */
  }
}
